css:
.rm-t-warm-sand{padding:0 0 50px;color:#40372c;background:#fcf8f1;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;}
.rm-t-warm-sand .rm-head{padding:52px 58px 26px;background:linear-gradient(180deg,#faf2e4 0%,#fdfaf4 100%);border-bottom:1px solid #e6d7c1;}
.rm-t-warm-sand .rm-name{font-family:Georgia,"Songti SC","STSong","Noto Serif SC",serif;font-size:40px;font-weight:600;letter-spacing:.06em;line-height:1.16;color:#4a3a28;}
.rm-t-warm-sand .rm-role{margin:10px 0 0;font-size:12.5px;letter-spacing:.16em;color:#9c7b52;}
.rm-t-warm-sand .rm-contact{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px 24px;margin-top:20px;}
.rm-t-warm-sand .rm-k{font-size:9.5px;letter-spacing:.14em;color:#b39a7c;}
.rm-t-warm-sand .rm-v{font-size:11.5px;color:#53452f;}
.rm-t-warm-sand .rm-body{padding:0 58px;}
.rm-t-warm-sand .rm-sec{margin-top:24px;}
.rm-t-warm-sand .rm-sec-h{display:flex;align-items:center;gap:12px;margin:0 0 11px;padding-bottom:7px;}
.rm-t-warm-sand .rm-sec-t{flex:0 0 auto;font-family:Georgia,"Songti SC","STSong","Noto Serif SC",serif;font-size:14.5px;letter-spacing:.16em;color:#8a5f34;}
.rm-t-warm-sand .rm-sec-h::after{content:"";flex:1 1 auto;height:1px;background:linear-gradient(90deg,#e6d7c1,#f4ebdd);}
.rm-t-warm-sand .rm-item{margin-bottom:13px;}
.rm-t-warm-sand .rm-item-t{font-size:13.5px;font-weight:600;color:#4a3a28;}
.rm-t-warm-sand .rm-item-role{font-size:12px;color:#8a7454;}
.rm-t-warm-sand .rm-date{font-size:10.5px;font-style:italic;letter-spacing:.02em;color:#a08a6c;}
.rm-t-warm-sand .rm-item-sub{font-size:11.5px;color:#8a7454;}
.rm-t-warm-sand .rm-edu-courses{font-size:11px;color:#8a7454;}
.rm-t-warm-sand .rm-bullets{padding-left:15px;}
.rm-t-warm-sand .rm-bullets li{margin:3px 0;}
.rm-t-warm-sand .rm-bullets li::marker{color:#c9a97c;}
.rm-t-warm-sand .rm-summary{font-size:12.5px;line-height:1.78;color:#4b4030;}
.rm-t-warm-sand .rm-tag{background:#f5ebda;border:1px solid #e8d7bd;border-radius:4px;color:#7a5a34;font-size:11px;}
.rm-t-warm-sand .rm-skill-row{grid-template-columns:94px minmax(0,1fr);gap:10px;margin-bottom:7px;}
.rm-t-warm-sand .rm-skill-k{font-size:11.5px;font-weight:600;color:#8a5f34;}
.rm-t-warm-sand .rm-award-row{margin-bottom:6px;padding-bottom:5px;border-bottom:1px dashed #eadcc6;}
.rm-t-warm-sand .rm-award-row:last-child{border-bottom:none;}
.rm-t-warm-sand .rm-award-t{font-size:12.5px;color:#4a3a28;}
.rm-t-warm-sand .rm-award-desc{font-size:11px;color:#8a7454;}
.rm-t-warm-sand .rm-sec-campus .rm-item{margin-bottom:9px;}
.rm-t-warm-sand .rm-sec-hobbies .rm-tags{gap:7px;}
